/** Abrupt source-only and endpoint-only chunk saves execute the real asynchronous write-ahead path. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearJournalRecoveryChecks {
    private static final BlockPos ROOT=new BlockPos(15,100,8),SOURCE=ROOT.east(2),ACTIVE=ROOT.east(),UNRELATED=ROOT.east(8);
    private static final AtomicBoolean pause=new AtomicBoolean(),prepared=new AtomicBoolean(),baselineDone=new AtomicBoolean();private static boolean running,fired,baseline;private static int stage,ticks,checks;private static ServerLevel world;private static Actor actor;
    private static String mode(){return System.getProperty("vandorlabs.gearJournalPhase","");}
    private static boolean enabled(){return Set.of("crash-source","recover-source","crash-target","recover-target","prepared-edit","io-failure").contains(mode());}
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel world){super(world,new com.mojang.authlib.GameProfile(new UUID(0,6211210),"GearRecovery"));}}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native gear recovery "+mode()+" stage="+stage+" tick="+ticks+": "+why);}
    private static NativeGearEntity root(){var tile=NativeGearFormation.at(world,ROOT);need(tile!=null&&!tile.inert(),"healthy root");return tile;}
    private static int nativeCount(BlockPos pos){return world.getBlockEntity(pos) instanceof ChestBlockEntity chest?chest.getItem(0).getCount():0;}
    private static int captured(){var payload=root().payload();if(payload==null||payload.materialized())return 0;var staged=NativeGearSnapshot.stage(world,payload.cells().getFirst(),false);return staged instanceof ChestBlockEntity chest?chest.getItem(0).getCount():0;}
    private static void click(){actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);actor.setPos(15.5,101,5);need(actor.gameMode.useItemOn(actor,world,ItemStack.EMPTY,InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(ROOT).add(0,0,-.5),Direction.NORTH,ROOT,false)).consumesAction(),"actual player manual activation");}
    private static CompletableFuture<Void> saveChunk(BlockPos pos){var chunk=world.getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4);need(chunk!=null,"loaded physical checkpoint chunk");return world.getChunkSource().chunkMap.write(new ChunkPos(pos),ChunkSerializer.write(world,chunk)).thenCompose(ignored->((NativeRampChunkStorageAccess)(Object)world.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true));}
    private static void abrupt(){System.out.println("[vandorlabs][gear-recovery] "+mode()+" PASS checks="+checks+" realAsyncJournal/ARMEDbeforeMutation/partialCrossChunkSave/abruptHalt");System.out.flush();Runtime.getRuntime().halt(0);}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);for(int x=-1;x<=2;x++)for(int z=-1;z<=1;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}if(mode().startsWith("recover-")){var root=root();need(root.progress()==(mode().equals("recover-source")?1:0)&&root.blocked(),"last valid endpoint restored before gameplay");need(root.saveWithoutMetadata(world.registryAccess()).getByteArray("NativeGearRootOpaque").length==512,"opaque root before-image retained");if(mode().equals("recover-source")){need(root.payload()==null&&nativeCount(SOURCE)==7&&NativeGearFormation.at(world,ACTIVE)!=null&&ROOT.equals(NativeGearFormation.at(world,ACTIVE).owner()),"source-only save restored exactly one native owner");need(((ChestBlockEntity)world.getBlockEntity(SOURCE)).getPersistentData().getByteArray("NativeGearOpaque").length==512,"native source opaque bytes");}else{need(captured()==7&&nativeCount(ACTIVE)==0&&NativeGearFormation.at(world,ACTIVE)!=null&&ROOT.equals(NativeGearFormation.at(world,ACTIVE).owner())&&world.getBlockState(SOURCE).isAir(),"target-only save rolls native occurrence back to exactly one captured owner");need(world.getBlockState(UNRELATED).is(Blocks.GOLD_BLOCK),"newer unrelated same-chunk write preserved");}root.authorize(actor);click();stage=10;running=true;return;}
        for(int x=9;x<=25;x++)for(int y=95;y<=105;y++)for(int z=3;z<=13;z++)world.setBlock(new BlockPos(x,y,z),y==95?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),18);world.setBlock(ROOT.west(),Blocks.STONE.defaultBlockState(),3);actor.setPos(15.5,101,5);var stack=new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.EXTENDER.id),2);actor.setItemInHand(InteractionHand.MAIN_HAND,stack);for(var at:List.of(ROOT,ROOT.east()))need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(at.west()).add(.5,0,0),Direction.EAST,at.west(),false)).consumesAction(),"actual supported Survival arm placement");need(stack.isEmpty(),"exact two source sections consumed");NativeGearJournal.testPause=pause::get;stage=0;running=true;
        }catch(Throwable failure){fail(failure);}}
    private static void faults(String where){if(mode().equals("io-failure")&&where.equals("before-write")&&!fired){fired=true;throw new java.io.UncheckedIOException(new java.io.IOException("injected asynchronous preparation disk failure"));}if(mode().equals("prepared-edit")&&where.equals("after-publication")&&!prepared.get()){pause.set(true);prepared.set(true);}if(mode().equals("crash-source")&&where.equals("after-cell")&&!fired){fired=true;pause.set(true);need(root().payload()!=null&&!root().payload().materialized()&&nativeCount(SOURCE)==0,"capture published in memory under exact holds");saveChunk(SOURCE).thenRun(NativeGearJournalRecoveryChecks::abrupt);}if(mode().equals("crash-target")){if(where.equals("prepared-durable")&&root().progress()==0&&!baseline){baseline=true;pause.set(true);need(captured()==7&&nativeCount(ACTIVE)==0,"captured owner before endpoint arm");world.setBlock(UNRELATED,Blocks.GOLD_BLOCK.defaultBlockState(),18);saveChunk(ROOT).thenRun(()->baselineDone.set(true));}if(where.equals("after-cell")&&root().payload()!=null&&root().payload().materialized()&&!fired){fired=true;pause.set(true);need(nativeCount(ACTIVE)==7&&nativeCount(SOURCE)==0,"endpoint native inventory published under hold");saveChunk(ACTIVE).thenRun(NativeGearJournalRecoveryChecks::abrupt);}}}
    @SubscribeEvent(priority=EventPriority.LOWEST) public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<1200,"timeout "+root().error()+" phase="+root().progress()+" busy="+NativeGearJournal.busy(root()));if(stage==0){if(!root().controller()||root().assembly().columnHeight()!=2)return;world.setBlock(SOURCE,Blocks.CHEST.defaultBlockState(),3);var chest=(ChestBlockEntity)world.getBlockEntity(SOURCE);chest.setItem(0,new ItemStack(Items.DIAMOND,7));chest.getPersistentData().putByteArray("NativeGearOpaque",new byte[512]);chest.setChanged();var saved=root().saveWithoutMetadata(world.registryAccess());saved.putByteArray("NativeGearRootOpaque",new byte[512]);root().loadWithComponents(saved,world.registryAccess());root().authorize(actor);world.getServer().saveEverything(true,true,true);NativeGearJournal.testFault=NativeGearJournalRecoveryChecks::faults;click();stage=1;return;}
        if(stage==1){if(mode().equals("prepared-edit")&&prepared.get()&&pause.get()){need(nativeCount(SOURCE)==7&&!NativeGearHolds.blocked(world,SOURCE)&&!root().blocked(),"prepared disk record leaves original source usable");((ChestBlockEntity)world.getBlockEntity(SOURCE)).setItem(0,new ItemStack(Items.DIAMOND,11));click();NativeGearJournal.testFault=null;pause.set(false);stage=2;return;}if(mode().equals("io-failure")&&root().blocked()){need(fired&&nativeCount(SOURCE)==7&&root().payload()==null&&!NativeGearHolds.blocked(world,SOURCE),"real asynchronous I/O failure retains usable original inventory");finish();return;}if(mode().equals("crash-target")&&baselineDone.get())pause.set(false);need(!root().blocked()||mode().equals("io-failure"),"journal path refused "+root().error());return;}
        if(stage==2){if(NativeGearJournal.busy(root()))return;need(root().progress()==1&&root().target()&&!root().blocked()&&root().payload()==null&&nativeCount(SOURCE)==11&&NativeGearFormation.at(world,ACTIVE)!=null&&ROOT.equals(NativeGearFormation.at(world,ACTIVE).owner()),"prepared cancellation preserves newer native edit and manual reversal");finish();return;}
        if(stage==10){need(!root().blocked(),"recovered journal retries through real activation "+root().error());if(NativeGearJournal.busy(root())||root().payload()==null||!root().payload().materialized())return;if(mode().equals("recover-source")){if(root().progress()!=0)return;need(nativeCount(ACTIVE)==7&&nativeCount(SOURCE)==0,"source recovery new stroke owns exactly seven native diamonds");click();stage=11;}else{if(root().progress()!=1)return;need(nativeCount(SOURCE)==7&&nativeCount(ACTIVE)==0&&captured()==0,"target recovery reversed to one ordinary native Chest");finish();}return;}
        if(stage==11){if(NativeGearJournal.busy(root())||root().progress()!=1||root().payload()==null||!root().payload().materialized())return;need(nativeCount(SOURCE)==7&&nativeCount(ACTIVE)==0&&captured()==0,"source recovery reversal/native endpoint");finish();}
        }catch(Throwable failure){fail(failure);}}
    private static void finish(){running=false;NativeGearJournal.testFault=null;NativeGearJournal.testPause=null;System.out.println("[vandorlabs][gear-recovery] "+mode()+" PASS checks="+checks+" exactOneInventoryOwner/opaqueBeforeImages/nativeRetry/reversal/realAsyncCompletion");world.getServer().saveEverything(true,true,true);world.getServer().halt(false);}
    private static void fail(Throwable failure){running=false;NativeGearJournal.testFault=null;NativeGearJournal.testPause=null;failure.printStackTrace();System.out.println("[vandorlabs][gear-recovery] "+mode()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
